-- Version 1: reviewed synthetic schema export, no household records or automatic legacy baseline.
create table accounts (balance float(53) not null, id varchar(64) not null, type varchar(64) not null, name varchar(128) not null, primary key (id));
create table cash_position_lines (line_order integer not null check ((line_order>=0)), amount_minor bigint not null, snapshot_id varchar(36) not null, label varchar(100) not null, kind enum ('CASH','COMMITMENT') not null, primary key (line_order, snapshot_id));
create table cash_position_snapshots (as_of_date date not null, minimum_reserve_minor bigint not null, recorded_at timestamp(6) with time zone not null, verification varchar(16) not null, id varchar(36) not null, source_note varchar(200) not null, primary key (id));
create table categories (budget varchar(64) not null, id varchar(64) not null, name varchar(128) not null, primary key (id));
create table commitments (amount float(53) not null, due_date varchar(32) not null, category varchar(64), id varchar(64) not null, title varchar(128) not null, primary key (id));
create table decision_plans (updated_at timestamp(6) with time zone not null, version bigint not null, id varchar(36) not null, payload clob not null, primary key (id));
create table forecast_plans (updated_at timestamp(6) with time zone not null, version bigint not null, id varchar(36) not null, payload clob not null, primary key (id));
create table ledger_accounts (opening_date date not null, reconciled_date date, kind varchar(8) not null, opening_minor bigint not null, reconciled_balance bigint, reconciled_revision bigint, revision bigint not null, id varchar(36) not null, sandbox_identity varchar(64) unique, name varchar(100) not null, reconciled_source varchar(200), source varchar(200) not null, primary key (id));
create table ledger_audit (recorded_at timestamp(6) with time zone not null, action varchar(24) not null, account_id varchar(36) not null, id varchar(36) not null, source varchar(200) not null, after_json clob, before_json clob, primary key (id));
create table ledger_entries (activity_date date not null, amount_minor bigint not null, status varchar(8) not null, kind varchar(12) not null, account_id varchar(36) not null, id varchar(36) not null, reference varchar(100) not null, description varchar(160) not null, source varchar(200) not null, primary key (id), unique (account_id, reference));
create table migration_artifacts (created_at timestamp(6) with time zone not null, id bigint generated by default as identity, artifact_type varchar(64) not null, import_id varchar(64) not null, payload clob not null, primary key (id));
create table monthly_commitments (amount float(53) not null, day_of_month integer not null, category varchar(64), id varchar(64) not null, title varchar(128) not null, primary key (id));
create table transactions (amount float(53) not null, txn_date date not null, category varchar(64), id varchar(64) not null, source_monthly_commitment_id varchar(64), title varchar(128) not null, txn_type enum ('ACTUAL','MONTHLY_INSTANCE_FUTURE','ONE_OFF_FUTURE') not null, primary key (id));
alter table if exists cash_position_lines add constraint FKwuinh34wshgpl0itshra6owa foreign key (snapshot_id) references cash_position_snapshots;
